using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class LabLightAudit{
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Lighting/"));
 public static object FinalizeRecords(){foreach(string n in new[]{"C01_PortalTiles_20261107","C01_Lighting_20261107"})AssetDatabase.ImportAsset("Assets/Afrer_Seconds/06.Data/AssetSources/"+n+".json",ImportAssetOptions.ForceSynchronousImport);var s=SceneManager.GetActiveScene();var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");return new{dirty=s.isDirty,playing=Application.isPlaying,corridorDiffusers=root.GetComponentsInChildren<Renderer>().Count(r=>!r.transform.IsChildOf(room)&&r.sharedMaterials.Any(m=>m.name=="CL_Lamp"))};}
 public static object Restore(){if(Application.isPlaying)throw new Exception("Stop play first");var s=SceneManager.GetActiveScene();if(!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Unexpected scene");EditorSceneManager.OpenScene(s.path);return Run();}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var mat=AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/CL_Lamp.mat");var checks=new List<object>();foreach(var t in room.Cast<Transform>().Where(t=>t.name.StartsWith("S1_WallTaskLight"))){var l=t.GetComponentInChildren<Light>();var diffuser=t.TransformPoint(new Vector3(0,-.1125f,.82f));checks.Add(new{name=t.name,diffuserToLightMeters=Vector3.Distance(diffuser,l.transform.position),beamVsDiffuserNormalDegrees=Vector3.Angle(l.transform.forward,-t.up),l.intensity,l.spotAngle,fixtureEmits=t.GetComponentsInChildren<Renderer>().Any(r=>r.sharedMaterials.Contains(mat))});}var pod=room.Find("Pod_Interior_Task").GetComponent<Light>();var g=room.Find("CL_PodCeilingLight");var meshes=g.GetComponentsInChildren<MeshFilter>();int bad=0;foreach(var mf in meshes){var vs=mf.sharedMesh.vertices;var ts=mf.sharedMesh.triangles;for(int i=0;i<ts.Length;i+=3)if(Vector3.Cross(vs[ts[i+1]]-vs[ts[i]],vs[ts[i+2]]-vs[ts[i]]).magnitude*.5f<5e-9f)bad++;}var active=room.GetComponentsInChildren<Light>().Where(l=>l.enabled).ToArray();var result=new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,background=Application.runInBackground,lights=checks,activeRoomLights=active.Select(l=>l.name).ToArray(),activeFloatingHelpers=room.Find("C01_Perimeter_Lab/Integrated_Worklights").GetComponentsInChildren<Light>().Count(l=>l.enabled),unattachedFillEnabled=room.Find("Measurement_Indirect").GetComponent<Light>().enabled,podDiffuserToLightMeters=Vector3.Distance(g.position-Vector3.up*.012f,pod.transform.position),podBeamNormalError=Vector3.Angle(pod.transform.forward,Vector3.down),lampKeyword=mat.IsKeywordEnabled("_EMISSION"),lampFlags=mat.globalIlluminationFlags.ToString(),newMeshTriangles=meshes.Sum(m=>m.sharedMesh.triangles.Length/3),degenerateTriangles=bad,player=s.GetRootGameObjects().Single(o=>o.name.StartsWith("Player")).transform.position.ToString("F5")};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
